// Gather RSS headlines + target-site context, build the Gemini prompt
const feedItems = $input.all()
  .filter(i => i.json && i.json.title)
  .slice(0, 18)
  .map(i => ({ title: i.json.title, source: (i.json.link || '').split('/')[2] || 'rss', published: i.json.pubDate || i.json.isoDate || '' }));

let siteTitle = '';
let siteSnippet = '';
try {
  const html = ($('🌐 Scrape target site').first().json.data || '').toString();
  const t = html.match(/<title[^>]*>([^<]+)<\/title>/i);
  siteTitle = t ? t[1].trim() : '';
  const txt = html.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  siteSnippet = txt.slice(0, 1200);
} catch (e) { /* site scrape optional */ }

const brand = $('⚙️ CONFIG').first().json.brandName;
const today = new Date().toISOString().slice(0, 10);

const prompt = `You are the growth-operations AI for ${brand}, a proprietary trading firm offering funded-trader challenges with profit splits and fast payouts.

TODAY: ${today}

TARGET WEBSITE SNAPSHOT (market context):
Title: ${siteTitle}
Content snippet: ${siteSnippet}

LATEST MARKET HEADLINES (RSS):
${feedItems.map((h, i) => `${i + 1}. [${h.source}] ${h.title}`).join('\n')}

TASK — return STRICT JSON only (no markdown, no backticks) with exactly these keys:
{
  "market_summary": "3-4 sentence digest of what moved markets and why it matters to retail prop traders",
  "sentiment": "risk-on | risk-off | mixed",
  "sentiment_reason": "one sentence",
  "content_angles": ["angle 1", "angle 2", "angle 3"],
  "social_posts": {
    "x": "max 260 chars, punchy, include relevant hashtags such as #PropTrading",
    "linkedin": "120-180 words, professional tone",
    "discord": "community style, emojis allowed, 2-4 lines"
  },
  "blog_idea": "one blog title for the firm's blog tied to today's markets",
  "seo_keywords": ["kw1", "kw2", "kw3", "kw4", "kw5"]
}`;

return [{ json: { date: today, headlines: feedItems, siteTitle, prompt } }];

// Parse Gemini JSON response robustly
let raw = '';
try { raw = $json.candidates[0].content.parts[0].text || ''; } catch (e) { raw = ''; }
raw = raw.replace(/```json|```/g, '').trim();
let brief = {};
try { brief = JSON.parse(raw); } catch (e) {
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) { try { brief = JSON.parse(m[0]); } catch (e2) { brief = {}; } }
}
const date = $('🧮 Aggregate & Build Prompt').first().json.date;
return [{ json: {
  date,
  market_summary: brief.market_summary || '(no summary generated)',
  sentiment: brief.sentiment || 'mixed',
  sentiment_reason: brief.sentiment_reason || '',
  content_angles: Array.isArray(brief.content_angles) ? brief.content_angles : [],
  post_x: (brief.social_posts && brief.social_posts.x) || '',
  post_linkedin: (brief.social_posts && brief.social_posts.linkedin) || '',
  post_discord: (brief.social_posts && brief.social_posts.discord) || '',
  blog_idea: brief.blog_idea || '',
  seo_keywords: Array.isArray(brief.seo_keywords) ? brief.seo_keywords : [],
  headline_count: ($('🧮 Aggregate & Build Prompt').first().json.headlines || []).length
} }];

