const lead = $json.body || {};
const brand = $('⚙️ CONFIG (Leads)').first().json.brandName;
const prompt = `You are the lead-qualification AI for ${brand}, a prop trading firm offering funded-trader challenges ($5K/$10K/$25K/$50K/$100K/$200K accounts, 2-step evaluation, fast payouts, high profit split).

INCOMING LEAD:
Name: ${lead.name || ''}
Email: ${lead.email || ''}
Country: ${lead.country || ''}
Trading experience: ${lead.experience || ''}
Available capital for challenge fee: ${lead.capital || ''}
Message: ${lead.message || ''}

TASK — return STRICT JSON only (no markdown) with exactly these keys:
{
  "score": <integer 1-10, likelihood this lead buys a challenge>,
  "persona": "one of: Aspiring Beginner | Retail Grinder | Experienced Pro | Funded Veteran | Skeptical Browser",
  "recommended_challenge": "e.g. $25K 2-Step Challenge",
  "reasoning": "2 sentences max",
  "draft_reply": "a warm, personalized 100-140 word email reply from the ${brand} team, referencing their experience and the recommended challenge, with a subtle CTA"
}`;
return [{ json: { lead, prompt } }];

let raw = '';
try { raw = $json.candidates[0].content.parts[0].text || ''; } catch (e) {}
raw = raw.replace(/```json|```/g, '').trim();
let s = {};
try { s = JSON.parse(raw); } catch (e) { const m = raw.match(/\{[\s\S]*\}/); if (m) { try { s = JSON.parse(m[0]); } catch (e2) {} } }
const lead = $('🧮 Build Scoring Prompt').first().json.lead || {};
return [{ json: {
  received_at: new Date().toISOString(),
  name: lead.name || '', email: lead.email || '', country: lead.country || '',
  experience: lead.experience || '', capital: lead.capital || '', message: lead.message || '',
  score: Number(s.score) || 0,
  persona: s.persona || 'Unknown',
  recommended_challenge: s.recommended_challenge || '',
  reasoning: s.reasoning || '',
  draft_reply: s.draft_reply || ''
} }];

// Input 0: site check result or error. Trustpilot text is read from its own node.
let statusCode = 0, siteOk = false;
const siteItem = $input.all()[0].json;
if (siteItem.error) { statusCode = 0; siteOk = false; }
else { siteOk = true; statusCode = 200; }

let rating = null;
try {
  const tp = ($('⭐ Scrape Trustpilot Rating').first().json.data || '').toString();
  const head = tp.slice(0, 300);
  const i = head.indexOf(' with ');
  if (i >= 0) {
    const m = head.slice(i, i + 20).match(/[0-9][.][0-9]|[0-9]/);
    if (m) rating = parseFloat(m[0]);
  }
} catch (e) {}

return [{ json: {
  checked_at: new Date().toISOString(),
  url: $('⚙️ CONFIG (Monitor)').first().json.targetUrl,
  site_up: siteOk,
  status_code: statusCode,
  trustpilot_rating: rating
} }];

