const e = $json;
const wf = (e.workflow && e.workflow.name) || 'unknown workflow';
const node = (e.execution && e.execution.lastNodeExecuted) || 'unknown node';
const msg = (e.execution && e.execution.error && e.execution.error.message) || 'unknown error';
const url = (e.execution && e.execution.url) || '';
return [{ json: { wf, node, msg, url, at: new Date().toISOString() } }];

// One Telegram approval request per queued post (ids come from the dashboard response)
const res = $input.first().json || {};
const posts = Array.isArray(res.posts) ? res.posts : [];
const label = { x: 'X / Twitter', linkedin: 'LinkedIn', discord: 'Discord' };
return posts.map(p => ({ json: {
  id: p.id,
  platform: p.platform,
  text: ('📝 Post awaiting approval — ' + (label[p.platform] || p.platform) + ' (#' + p.id + ')\n\n' + p.content).slice(0, 3900)
} }));
